class Weapon {
    constructor(name, baseDamage) {
        this.name = name;
        this.baseDamage = baseDamage;
    }

    calculateDamage() {
        return this.baseDamage;
    }
}

class Sword extends Weapon {
    constructor(name, baseDamage, sharpness) {
        super(name, baseDamage);
        this.sharpness = sharpness;
    }

    calculateDamage() {
        return this.baseDamage + this.sharpness;
    }
}

class Bow extends Weapon {
    constructor(name, baseDamage, drawStrength) {
        super(name, baseDamage);
        this.drawStrength = drawStrength;
    }

    calculateDamage() {
        return this.baseDamage * this.drawStrength;
    }
}

// Test cases - do not modify
const basicWeapon = new Weapon("Dagger", 7);
console.log(`Basic Weapon Damage: ${basicWeapon.calculateDamage()}`);

const broadsword = new Sword("Broadsword", 12, 5);
console.log(`Broadsword Damage: ${broadsword.calculateDamage()}`);

const longbow = new Bow("Longbow", 8, 2);
console.log(`Longbow Damage: ${longbow.calculateDamage()}`);

